void ChatServer::handlePrivateMessage(const TcpConnectionPtr& conn, const std::string& payload) {
    std::string sender;
    TcpConnectionPtr targetConn;

    // payload 格式: targetUser\0messageContent
    size_t nullPos = payload.find('\0');
    if (nullPos == std::string::npos) {
        conn->send(makeAckMessage("Invalid private message format."));
        return;
    }

    std::string targetUser = payload.substr(0, nullPos);
    std::string content = payload.substr(nullPos + 1);

    {
        std::lock_guard<std::mutex> lock(mutex_);
        auto itSender = connToUser_.find(conn.get());
        if (itSender == connToUser_.end()) {
            conn->send(makeAckMessage("Please login first."));
            return;
        }
        sender = itSender->second;

        auto itTarget = users_.find(targetUser);
        if (itTarget == users_.end()) {
            conn->send(makeAckMessage("User '" + targetUser + "' not found."));
            return;
        }
        targetConn = itTarget->second;
    }

    // 发送私聊消息给目标用户
    targetConn->send(makeBroadcastMessage("[PM from " + sender + "]: " + content));
    // 发送确认给发送者
    conn->send(makeAckMessage("PM sent to " + targetUser));
    std::cout << "[ChatServer] PM from '" << sender << "' to '" << targetUser << "'" << std::endl;
}

void ChatServer::handleLogout(const TcpConnectionPtr& conn) {
    conn->send(makeAckMessage("Goodbye!"));
    conn->shutdown();
}

